import{_ as l,a0 as p,w as o,s as r,I as t,a1 as i,A as n,x as s,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何通过命令行升级 Debian 9 为 Debian 10 | LCTT x X-CMD","titleTemplate":false,"description":"如何通过命令行升级 Debian 9 为 Debian 10 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何通过命令行升级 Debian 9 为 Debian 10 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何通过命令行升级 Debian 9 为 Debian 10 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190720 How to Upgrade Debian 9 (Stretch) to Debian 10 (Buster) via Command Line","title":"如何通过命令行升级 Debian 9 为 Debian 10","tag":"201908","desc":""},"relativePath":"201908/20190720 How to Upgrade Debian 9 (Stretch) to Debian 10 (Buster) via Command Line.md","filePath":"[post].md"}'),u={name:"201908/20190720 How to Upgrade Debian 9 (Stretch) to Debian 10 (Buster) via Command Line.md"};function b(h,a,g,c,k,D){const e=p("Link");return o(),r("div",null,[t("p",null,[i(e,{href:"collector:",title:"lujun9972"},{default:n(()=>[...a[0]||(a[0]=[s("#",-1)])]),_:1}),a[5]||(a[5]=s(": subject: (How to Upgrade Debian 9 (Stretch) to Debian 10 (Buster) via Command Line) ",-1)),i(e,{href:"collector:",title:"lujun9972"},{default:n(()=>[...a[1]||(a[1]=[s("#",-1)])]),_:1}),a[6]||(a[6]=s(": via: (",-1)),i(e,{href:"https://www.linuxtechi.com/upgrade-debian-9-to-debian-10-command-line/"},{default:n(()=>[...a[2]||(a[2]=[s("https://www.linuxtechi.com/upgrade-debian-9-to-debian-10-command-line/",-1)])]),_:1}),a[7]||(a[7]=s(") ",-1)),i(e,{href:"collector:",title:"lujun9972"},{default:n(()=>[...a[3]||(a[3]=[s("#",-1)])]),_:1}),a[8]||(a[8]=s(": author: (Pradeep Kumar ",-1)),i(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...a[4]||(a[4]=[s("https://www.linuxtechi.com/author/pradeep/",-1)])]),_:1}),a[9]||(a[9]=s(")",-1))]),a[28]||(a[28]=t("h1",{id:"如何通过命令行升级-debian-9-为-debian-10",tabindex:"-1"},[s("如何通过命令行升级 Debian 9 为 Debian 10 "),t("a",{class:"header-anchor",href:"#如何通过命令行升级-debian-9-为-debian-10","aria-label":"Permalink to “如何通过命令行升级 Debian 9 为 Debian 10”"},"​")],-1)),t("p",null,[a[11]||(a[11]=s("我们已经在先前的文章中看到如何安装 ",-1)),i(e,{href:"https://linux.cn/article-11083-1.html"},{default:n(()=>[...a[10]||(a[10]=[s("Debian 10（Buster）",-1)])]),_:1}),a[12]||(a[12]=s("。今天，我们将学习如何从 Debian 9 升级为 Debian 10，虽然我们已将看到 Debian 10 和它的特色，所以这里我们不会深入介绍。但是可能读者没有机会读到那篇文章，让我们快速了解一下 Debian 10 和它的新功能。",-1))]),a[29]||(a[29]=d(`<p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Upgrade-Debian-9-to-Debian-10.jpg" alt=""></p><p>在差不多两年的开发后，Debian 团队最终发布一个稳定版本，Debian 10 的代码名称是 Buster。Buster 是一个 LTS (长期支持支持)版本，因此未来将由 Debian 支持 5 年。</p><h3 id="debian-10-buster-新的特色" tabindex="-1">Debian 10（Buster）新的特色 <a class="header-anchor" href="#debian-10-buster-新的特色" aria-label="Permalink to “Debian 10（Buster）新的特色”">​</a></h3><p>Debian 10（Buster）回报给大多数 Debian 爱好者大量的新特色。一些特色包括：</p><ul><li>GNOME 桌面 3.30</li><li>默认启用 AppArmor</li><li>支持 Linux 内核 4.19.0-4</li><li>支持 OpenJDk 11.0</li><li>从 Nodejs 4 ~ 8 升级到 Nodejs 10.15.2</li><li>Iptables 替换为 NFTables</li></ul><p>等等。</p><h3 id="从-debian-9-到-debian-10-的逐步升级指南" tabindex="-1">从 Debian 9 到 Debian 10 的逐步升级指南 <a class="header-anchor" href="#从-debian-9-到-debian-10-的逐步升级指南" aria-label="Permalink to “从 Debian 9 到 Debian 10 的逐步升级指南”">​</a></h3><p>在我们开始升级 Debian 10 前，让我们看看升级需要的必备条件：</p><h4 id="步骤-1-debian-升级必备条件" tabindex="-1">步骤 1) Debian 升级必备条件 <a class="header-anchor" href="#步骤-1-debian-升级必备条件" aria-label="Permalink to “步骤 1) Debian 升级必备条件”">​</a></h4><ul><li>一个良好的网络连接</li><li>root 用户权限</li><li>数据备份</li></ul><p>备份你所有的应用程序代码库、数据文件、用户账号详细信息、配置文件是极其重要的，以便在升级出错时，你可以总是可以还原到先前的版本。</p><h4 id="步骤-2-升级-debian-9-现有的软件包" tabindex="-1">步骤 2) 升级 Debian 9 现有的软件包 <a class="header-anchor" href="#步骤-2-升级-debian-9-现有的软件包" aria-label="Permalink to “步骤 2) 升级 Debian 9 现有的软件包”">​</a></h4><p>接下来的步骤是升级你所有现有的软件包，因为一些软件包被标志为保留不能升级，从 Debian 9 升级为 Debian 10 有失败或引发一些问题的可能性。所以，我们不冒任何风险，更好地升级软件包。使用下面的代码来升级软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update &amp;&amp; sudo apt upgrade -y</span></span></code></pre></div><h4 id="步骤-3-修改软件包存储库文件-etc-sources-list" tabindex="-1">步骤 3) 修改软件包存储库文件 /etc/sources.list <a class="header-anchor" href="#步骤-3-修改软件包存储库文件-etc-sources-list" aria-label="Permalink to “步骤 3) 修改软件包存储库文件 /etc/sources.list”">​</a></h4><p>接下来的步骤是修改软件包存储库文件 <code>/etc/sources.list</code>，你需要用文本 <code>Buster</code> 替换 <code>Stretch</code>。</p><p>但是，在你更改任何东西前，确保如下创建一个 <code>sources.list</code> 文件的备份：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo cp /etc/apt/sources.list /etc/apt/sources.list.bak</span></span></code></pre></div><p>现在使用下面的 <code>sed</code> 命令来在软件包存储库文件中使用 <code>buster</code> 替换 <code>stretch</code>，示例如下显示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo sed -i &#39;s/stretch/buster/g&#39; /etc/apt/sources.list</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo sed -i &#39;s/stretch/buster/g&#39; /etc/apt/sources.list.d/*.list</span></span></code></pre></div><p>更新后，你需要如下更新软件包存储库索引：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update</span></span></code></pre></div><p>在开始升级你现有的 Debian 操作系统前，让我们使用下面的命令验证当前版本，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ cat /etc/*-release</span></span>
<span class="line"><span>PRETTY_NAME=&quot;Debian GNU/Linux 9 (stretch)&quot;</span></span>
<span class="line"><span>NAME=&quot;Debian GNU/Linux&quot;</span></span>
<span class="line"><span>VERSION_ID=&quot;9&quot;</span></span>
<span class="line"><span>VERSION=&quot;9 (stretch)&quot;</span></span>
<span class="line"><span>ID=debian</span></span>
<span class="line"><span>HOME_URL=&quot;https://www.debian.org/&quot;</span></span>
<span class="line"><span>SUPPORT_URL=&quot;https://www.debian.org/support&quot;</span></span>
<span class="line"><span>BUG_REPORT_URL=&quot;https://bugs.debian.org/&quot;</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><h4 id="步骤-4-从-debian-9-升级到-debian-10" tabindex="-1">步骤 4) 从 Debian 9 升级到 Debian 10 <a class="header-anchor" href="#步骤-4-从-debian-9-升级到-debian-10" aria-label="Permalink to “步骤 4) 从 Debian 9 升级到 Debian 10”">​</a></h4><p>你做完所有的更改后，是时候从 Debian 9 升级到 Debian 10 了。但是在这之前，再次如下确保更新你的软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update &amp;&amp; sudo apt upgrade -y</span></span></code></pre></div><p>在软件包升级期间，你将被提示启动服务，所以选择你较喜欢的选项。</p><p>一旦你系统的所有软件包升级完成，就升级你的发行版的软件包。使用下面的代码来升级发行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt dist-upgrade -y</span></span></code></pre></div><p>升级过程可能花费一些时间，取决于你的网络速度。记住在升级过程中，你将被询问一些问题，在软件包升级后是否需要重启服务、你是否需要保留现存的配置文件等。如果你不想进行一些自定义更改，简单地键入 “Y” ，来让升级过程继续。</p><h4 id="步骤-5-验证升级" tabindex="-1">步骤 5) 验证升级 <a class="header-anchor" href="#步骤-5-验证升级" aria-label="Permalink to “步骤 5) 验证升级”">​</a></h4><p>一旦升级过程完成，重启你的机器，并使用下面的方法检测版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ lsb_release -a</span></span></code></pre></div><p>如果你获得如下输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Distributor ID: Debian</span></span>
<span class="line"><span>Description:    Debian GNU/Linux 10 (buster)</span></span>
<span class="line"><span>Release:        10</span></span>
<span class="line"><span>Codename:       buster</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>是的，你已经成功地从 Debian 9 升级到 Debian 10。</p><p>验证升级的备用方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ cat /etc/*-release</span></span>
<span class="line"><span>PRETTY_NAME=&quot;Debian GNU/Linux 10 (buster)&quot;</span></span>
<span class="line"><span>NAME=&quot;Debian GNU/Linux&quot;</span></span>
<span class="line"><span>VERSION_ID=&quot;10&quot;</span></span>
<span class="line"><span>VERSION=&quot;10 (buster)&quot;</span></span>
<span class="line"><span>VERSION_CODENAME=buster</span></span>
<span class="line"><span>ID=debian</span></span>
<span class="line"><span>HOME_URL=&quot;https://www.debian.org/&quot;</span></span>
<span class="line"><span>SUPPORT_URL=&quot;https://www.debian.org/support&quot;</span></span>
<span class="line"><span>BUG_REPORT_URL=&quot;https://bugs.debian.org/&quot;</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><h3 id="结束" tabindex="-1">结束 <a class="header-anchor" href="#结束" aria-label="Permalink to “结束”">​</a></h3><p>希望上面的逐步指南为你提供了从 Debian 9（Stretch）简单地升级为 Debian 10（Buster）的所有信息。在评论部分，请给予你使用 Debian 10 的反馈、建议、体验。</p><hr>`,42)),t("p",null,[a[14]||(a[14]=s("via: ",-1)),i(e,{href:"https://www.linuxtechi.com/upgrade-debian-9-to-debian-10-command-line/"},{default:n(()=>[...a[13]||(a[13]=[s("https://www.linuxtechi.com/upgrade-debian-9-to-debian-10-command-line/",-1)])]),_:1})]),t("p",null,[a[19]||(a[19]=s("作者：",-1)),i(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...a[15]||(a[15]=[s("Pradeep Kumar",-1)])]),_:1}),a[20]||(a[20]=s(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[16]||(a[16]=[s("lujun9972",-1)])]),_:1}),a[21]||(a[21]=s(" 译者：",-1)),i(e,{href:"https://github.com/robsean"},{default:n(()=>[...a[17]||(a[17]=[s("robsean",-1)])]),_:1}),a[22]||(a[22]=s(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[18]||(a[18]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[25]||(a[25]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[23]||(a[23]=[s("LCTT",-1)])]),_:1}),a[26]||(a[26]=s(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...a[24]||(a[24]=[s("Linux中国",-1)])]),_:1}),a[27]||(a[27]=s(" 荣誉推出",-1))])])}const w=l(u,[["render",b]]);export{x as __pageData,w as default};
